// fixture.go — 框架層級的測試工廠（fluent test request builder）。
// 自 v0.8.11 由原 pkg/fixture 合併進 pkg/contract，以收斂套件數量。
//
// 讓 AI 和人都能用 fluent API 建立完整的測試請求：
//
//	result := contract.Request(router).
//	    POST("/api/users").
//	    WithJSON(map[string]string{"name": "test"}).
//	    WithHeader("Authorization", "Bearer token").
//	    Expect(201).
//	    Run(t)
//
// @ai:generated by=claude-opus-4-6 date=2026-02-27
package contract

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/maoxiaoyue/hypgo/pkg/router"
)

// RequestBuilder 提供 fluent API 建立測試請求
type RequestBuilder struct {
	router       *router.Router
	method       string
	path         string
	body         string
	headers      map[string]string
	query        map[string]string
	expectStatus int
	err          error // 建構階段的錯誤（如 WithJSON 序列化失敗），於 Run 時回報
}

// Request 建立新的 RequestBuilder
func Request(r *router.Router) *RequestBuilder {
	return &RequestBuilder{
		router:  r,
		method:  "GET",
		headers: make(map[string]string),
		query:   make(map[string]string),
	}
}

// GET 設定 GET 請求
func (b *RequestBuilder) GET(path string) *RequestBuilder {
	b.method = "GET"
	b.path = path
	return b
}

// POST 設定 POST 請求
func (b *RequestBuilder) POST(path string) *RequestBuilder {
	b.method = "POST"
	b.path = path
	return b
}

// PUT 設定 PUT 請求
func (b *RequestBuilder) PUT(path string) *RequestBuilder {
	b.method = "PUT"
	b.path = path
	return b
}

// DELETE 設定 DELETE 請求
func (b *RequestBuilder) DELETE(path string) *RequestBuilder {
	b.method = "DELETE"
	b.path = path
	return b
}

// PATCH 設定 PATCH 請求
func (b *RequestBuilder) PATCH(path string) *RequestBuilder {
	b.method = "PATCH"
	b.path = path
	return b
}

// WithJSON 設定 JSON body（自動設定 Content-Type）
func (b *RequestBuilder) WithJSON(v interface{}) *RequestBuilder {
	data, err := json.Marshal(v)
	if err != nil {
		// 先前靜默改送 "{}"，測試會在離原因很遠的地方失敗
		b.err = fmt.Errorf("WithJSON: %w", err)
	}
	b.body = string(data)
	b.headers["Content-Type"] = "application/json"
	return b
}

// WithBody 設定原始 body
func (b *RequestBuilder) WithBody(body string) *RequestBuilder {
	b.body = body
	return b
}

// WithHeader 設定請求標頭
func (b *RequestBuilder) WithHeader(key, value string) *RequestBuilder {
	b.headers[key] = value
	return b
}

// WithQuery 設定 query 參數
func (b *RequestBuilder) WithQuery(key, value string) *RequestBuilder {
	b.query[key] = value
	return b
}

// Expect 設定期望的狀態碼
func (b *RequestBuilder) Expect(status int) *RequestBuilder {
	b.expectStatus = status
	return b
}

// buildRequest 組出測試請求（body、標頭、query），RequestBuilder 與 TestCase 共用
func buildRequest(method, target, body string, headers, query map[string]string) *http.Request {
	req := httptest.NewRequest(method, target, strings.NewReader(body))
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	if len(query) > 0 {
		q := req.URL.Query()
		for k, v := range query {
			q.Set(k, v)
		}
		req.URL.RawQuery = q.Encode()
	}
	return req
}

// Run 執行測試請求並回傳結果
func (b *RequestBuilder) Run(t *testing.T) *TestResult {
	t.Helper()
	if b.err != nil {
		t.Fatalf("%s %s: %v", b.method, b.path, b.err)
	}

	w := httptest.NewRecorder()
	b.router.ServeHTTP(w, buildRequest(b.method, b.path, b.body, b.headers, b.query))

	result := &TestResult{
		Status:  w.Code,
		Body:    w.Body.Bytes(),
		Headers: w.Header(),
	}

	// 驗證狀態碼
	if b.expectStatus > 0 && w.Code != b.expectStatus {
		t.Errorf("%s %s: status = %d, want %d\nBody: %s",
			b.method, b.path, w.Code, b.expectStatus, w.Body.String())
	}

	return result
}
